PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE events (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      vertical TEXT NOT NULL CHECK(vertical IN ('wedding', 'birthday', 'community')),
      target_budget REAL NOT NULL DEFAULT 0,
      total_spent REAL NOT NULL DEFAULT 0,
      guest_count INTEGER NOT NULL DEFAULT 0,
      event_date TEXT NOT NULL,
      location TEXT NOT NULL,
      theme TEXT NOT NULL,
      notes TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    , user_id TEXT DEFAULT 'usr_planner_elena');
CREATE TABLE budget_items (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
      category TEXT NOT NULL,
      name TEXT NOT NULL,
      estimated_cost REAL NOT NULL DEFAULT 0,
      actual_cost REAL NOT NULL DEFAULT 0,
      status TEXT NOT NULL CHECK(status IN ('planned', 'booked', 'paid')),
      notes TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL
    );
CREATE TABLE timeline_items (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
      time_start TEXT NOT NULL,
      time_end TEXT NOT NULL,
      phase TEXT NOT NULL,
      title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      responsible_party TEXT NOT NULL DEFAULT '',
      is_completed INTEGER NOT NULL DEFAULT 0,
      order_index INTEGER NOT NULL DEFAULT 0
    );
CREATE TABLE vendor_items (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
      category TEXT NOT NULL,
      name TEXT NOT NULL,
      contact_email TEXT NOT NULL DEFAULT '',
      contact_phone TEXT NOT NULL DEFAULT '',
      status TEXT NOT NULL CHECK(status IN ('researching', 'contacted', 'quoted', 'hired', 'declined')),
      price REAL NOT NULL DEFAULT 0,
      notes TEXT NOT NULL DEFAULT '',
      deadline_offset_days INTEGER NOT NULL DEFAULT 0
    );
CREATE TABLE ideas (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
      category TEXT NOT NULL,
      title TEXT NOT NULL,
      description TEXT NOT NULL,
      aesthetic_tags TEXT NOT NULL DEFAULT '',
      ai_rationale TEXT NOT NULL DEFAULT ''
    );
CREATE TABLE guests (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
      name TEXT NOT NULL,
      email TEXT NOT NULL DEFAULT '',
      rsvp_status TEXT NOT NULL CHECK(rsvp_status IN ('attending', 'declined', 'pending')),
      dietary_restrictions TEXT NOT NULL DEFAULT '',
      table_number TEXT NOT NULL DEFAULT 'Unassigned',
      plus_ones INTEGER NOT NULL DEFAULT 0
    );
CREATE TABLE event_memories (
      id TEXT PRIMARY KEY,
      event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
      role TEXT NOT NULL CHECK(role IN ('user', 'assistant', 'system')),
      message TEXT NOT NULL,
      intent TEXT NOT NULL DEFAULT 'general',
      context_snapshot TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL
    );
CREATE TABLE knowledge_documents (
      id TEXT PRIMARY KEY,
      category TEXT NOT NULL,
      topic TEXT NOT NULL,
      title TEXT NOT NULL,
      content TEXT NOT NULL,
      tags TEXT NOT NULL
    );
CREATE TABLE users (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      email TEXT NOT NULL UNIQUE,
      password_hash TEXT NOT NULL,
      salt TEXT NOT NULL,
      role TEXT NOT NULL CHECK(role IN ('planner', 'couple', 'host', 'admin')),
      avatar_url TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL
    );
CREATE INDEX idx_budget_event ON budget_items(event_id);
CREATE INDEX idx_timeline_event ON timeline_items(event_id, order_index);
CREATE INDEX idx_vendor_event ON vendor_items(event_id);
CREATE INDEX idx_guests_event ON guests(event_id);
CREATE INDEX idx_memories_event ON event_memories(event_id);
CREATE INDEX idx_users_email ON users(email);
COMMIT;
